def solution():
    import heapq

    # Define the graph as an adjacency list
    graph = {
        2: {0: 6, 1: 5, 3: 3},
        1: {3: 2},
        3: {0: 3}
    }

    # Dijkstra's algorithm to find the shortest path from node 0 to node 3
    def dijkstra(graph, start, end):
        heap = [(0, start, [])]
        visited = set()
        while heap:
            (cost, node, path) = heapq.heappop(heap)
            if node in visited:
                continue
            visited.add(node)
            path = path + [node]
            if node == end:
                return (path, cost)
            for neighbor, weight in graph.get(node, {}).items():
                if neighbor not in visited:
                    heapq.heappush(heap, (cost + weight, neighbor, path))
        return None

    # Since the graph is not fully bidirectional, we need to consider reverse edges
    # Add reverse edges to the graph
    reverse_graph = {}
    for node in graph:
        for neighbor in graph[node]:
            if neighbor not in reverse_graph:
                reverse_graph[neighbor] = {}
            reverse_graph[neighbor][node] = graph[node][neighbor]

    # Combine the original and reverse graphs
    combined_graph = {node: dict(graph.get(node, {}), **reverse_graph.get(node, {})) for node in set(graph.keys()).union(reverse_graph.keys())}

    # Find the shortest path from 0 to 3
    path, distance = dijkstra(combined_graph, 0, 3)

    return (path, distance)
