def solution():
    import pulp

    # Define the graph edges
    edges = [
        (1, 4), (1, 7), (1, 9), (1, 10),
        (2, 5), (2, 10),
        (3, 5), (3, 9), (3, 10),
        (4, 6),
        (5, 8), (5, 10),
        (6, 9),
        (8, 9)
    ]

    # Define the problem
    prob = pulp.LpProblem('GraphColoring', pulp.LpStatusOptimal)

    # Define the colors
    colors = ['A', 'B', 'C']

    # Create variables for each vertex and color
    vertex_colors = {}
    for v in range(1, 11):
        for c in colors:
            vertex_colors[(v, c)] = pulp.LpVariable(f'v_{v}_c_{c}', cat='Binary')

    # Each vertex must have exactly one color
    for v in range(1, 11):
        prob += pulp.lpSum(vertex_colors[(v, c)] for c in colors) == 1

    # Adjacent vertices must have different colors
    for u, v in edges:
        for c in colors:
            prob += vertex_colors[(u, c)] + vertex_colors[(v, c)] <= 1

    # Solve the problem
    prob.solve()

    # Extract the color assignment
    color_assignment = {}
    for v in range(1, 11):
        for c in colors:
            if pulp.value(vertex_colors[(v, c)]) == 1:
                color_assignment[v] = c
                break

    return color_assignment
```

